changeSet.sql:
DO $$
DECLARE m record;
BEGIN
    FOR m IN SELECT g.rolname AS granted, u.rolname AS member
               FROM pg_auth_members a
               JOIN pg_roles g ON g.oid = a.roleid
               JOIN pg_roles u ON u.oid = a.member
               JOIN pg_roles o ON o.oid = a.grantor
              WHERE o.rolname = '${role}' LOOP
        EXECUTE format('REVOKE %I FROM %I GRANTED BY %I', m.granted, m.member, '${role}');
    END LOOP;
    EXECUTE format('DROP ROLE IF EXISTS %I', '${role}');
END
$$;
